 JsonNode profile(String kind){return data(call("POST",BASE+"/profiles",Map.of("kind",kind,"name","X01测试配置","scope",Map.of("ownerDeptId",Long.toString(COMPANY_A),"environment","TEST")),root));}
 String path(JsonNode p){return BASE+"/profiles/"+p.path("profileId").asText();}
