 Map<String,Object> draftBody(JsonNode p,Object cfg,Object creds){var b=new LinkedHashMap<String,Object>();b.put("kind",p.path("kind").asText());b.put("expectedVersion",p.path("version").asLong());b.put("config",cfg);b.put("reason","隔离测试保存");if(creds!=null)b.put("credentials",creds);return b;}
 JsonNode save(JsonNode p,Object cfg,Object creds){return data(call("PUT",path(p)+"/draft",draftBody(p,cfg,creds),root));}
 Object replace(String slot,String value){return Map.of(slot,Map.of("action","REPLACE","value",value));}
 JsonNode local(JsonNode p){return check(p,p.path("draftRevisionId").asText(),"LOCAL");}
 JsonNode check(JsonNode p,String revision,String level){return data(call("POST",path(p)+"/checks",Map.of("revisionId",revision,"expectedVersion",p.path("version").asLong(),"level",level),root));}
 Map<String,Object> publicationBody(JsonNode p,JsonNode check){return new LinkedHashMap<>(Map.of("revisionId",p.path("draftRevisionId").asText(),"expectedVersion",p.path("version").asLong(),"contentHash",p.path("draft").path("contentHash").asText(),"checkId",check.path("checkId").asText(),"reason","隔离验证发布"));}
 JsonNode pub(JsonNode p){data(call("POST",path(p)+"/publish",publicationBody(p,local(p)),root));return data(call("GET",path(p),null,root));}
 @Test void draftAndPublicationAreSeparateAndRuntimeUsesDatabase(){var p=save(profile("TENCENT_SMS"),config(true),replace("secretKey","isolated-secret"));assertTrue(p.path("activeRevisionId").isNull());assertThrows(com.xinyi.rongli.platform.error.ViException.class,()->runtime.withPublished(p.path("profileId").asLong(),COMPANY_A,"TENCENT_SMS",(r,c,s)->r));var active=pub(p);long rev=active.path("activeRevisionId").asLong();var next=save(active,config(false),null);assertEquals(rev,next.path("activeRevisionId").asLong());var captured=new ArrayList<byte[]>();assertEquals(Long.valueOf(rev),runtime.<Long>withPublished(active.path("profileId").asLong(),COMPANY_A,"TENCENT_SMS",(r,c,s)->{assertEquals("isolated-secret",new String(s.get("secretKey")));captured.add(s.get("secretKey"));return r;}));assertArrayEquals(new byte[captured.get(0).length],captured.get(0));assertEquals(rev,data(call("GET",path(p),null,root)).path("activeRevisionId").asLong());}
