 @Test void secretsEncryptedMaskedKeepClearAndMissingKeyFailClosed(){String secret="TEST-ONLY-"+UUID.randomUUID();var p=save(profile("TENCENT_SMS"),config(true),replace("secretKey",secret));String id=p.path("profileId").asText();assertFalse(p.toString().contains(secret));byte[] cipher=jdbc.queryForObject("SELECT ciphertext FROM vi_integration_secret WHERE profile_id=?",byte[].class,id);assertFalse(new String(cipher).contains(secret));p=save(p,config(true),Map.of("secretKey",Map.of("action","KEEP")));assertTrue(p.path("draft").path("settings").path("credentialStates").path("secretKey").path("configured").asBoolean());assertEquals(422,call("PUT",path(p)+"/draft",draftBody(p,config(true),replace("secretKey","***")),root).getStatusCode().value());String persisted=jdbc.queryForObject("SELECT GROUP_CONCAT(result_json) FROM vi_idempotency",String.class);assertFalse(persisted.contains(secret));var old=keys.getVersions();keys.setVersions(Map.of());try{assertEquals(503,call("PUT",path(p)+"/draft",draftBody(p,config(true),replace("secretKey","new-secret")),root).getStatusCode().value());assertEquals(503,call("POST",path(p)+"/checks",Map.of("revisionId",p.path("draftRevisionId").asText(),"expectedVersion",p.path("version").asLong(),"level","LOCAL"),root).getStatusCode().value());}finally{keys.setVersions(old);}var cleared=save(p,config(false),Map.of("secretKey",Map.of("action","CLEAR")));assertFalse(cleared.path("draft").path("settings").path("credentialStates").path("secretKey").path("configured").asBoolean());}
 @Test void publishedSecretsRetainedAndRevokedSecretCannotRollback(){var old=pub(save(profile("TENCENT_SMS"),config(true),replace("secretKey","old-isolated-key")));String oldRevision=old.path("activeRevisionId").asText();assertEquals(409,call("PUT",path(old)+"/draft",draftBody(old,config(false),Map.of("secretKey",Map.of("action","CLEAR"))),root).getStatusCode().value());var current=pub(save(old,config(true),replace("secretKey","new-isolated-key")));var c=check(current,oldRevision,"LOCAL");jdbc.update("UPDATE vi_integration_secret SET lifecycle='REVOKED' WHERE profile_id=? AND id=(SELECT CAST(JSON_UNQUOTE(JSON_EXTRACT(secret_refs_json,'$.secretKey')) AS UNSIGNED) FROM vi_integration_revision WHERE id=?)",current.path("profileId").asLong(),Long.parseLong(oldRevision));assertEquals(422,call("POST",path(current)+"/rollback",Map.of("targetRevisionId",oldRevision,"expectedVersion",current.path("version").asLong(),"reason","历史凭据已撤销","checkId",c.path("checkId").asText()),root).getStatusCode().value());assertEquals(current.path("activeRevisionId"),data(call("GET",path(current),null,root)).path("activeRevisionId"));}
 @Test void rollbackCreatesHistoryAndDoesNotMutateRevision(){var first=pub(save(profile("TENCENT_SMS"),config(false),null));String rev=first.path("activeRevisionId").asText();var next=pub(save(first,Map.of("apiVersion","2021-01-11","enabled",false,"signName","新签名"),null));var c=check(next,rev,"LOCAL");var result=data(call("POST",path(next)+"/rollback",Map.of("targetRevisionId",rev,"expectedVersion",next.path("version").asLong(),"reason","回滚历史配置","checkId",c.path("checkId").asText()),root));assertEquals("ROLLBACK",result.path("action").asText());assertEquals(3,ViJson.tree(call("GET",path(next)+"/publications",null,root).getBody()).path("total").asInt());assertEquals(2,ViJson.tree(call("GET",path(next)+"/revisions",null,root).getBody()).path("total").asInt());}
 @Test void scopeEnvironmentAndUntrustedFieldsFailClosed(){var p=profile("TENCENT_SMS");String a=scoped(COMPANY_A,"biz:integration:query","biz:integration:edit"),b=scoped(COMPANY_B,"biz:integration:query","biz:integration:edit");assertEquals(200,call("GET",path(p),null,a).getStatusCode().value());assertEquals(404,call("GET",path(p),null,b).getStatusCode().value());assertEquals(404,call("PUT",path(p)+"/draft",draftBody(p,config(false),null),b).getStatusCode().value());assertEquals(0,ViJson.tree(call("GET",BASE+"/profiles",null,b).getBody()).path("total").asInt());var fake=draftBody(p,config(false),null);fake.put("ownerDeptId",Long.toString(COMPANY_B));assertEquals(422,call("PUT",path(p)+"/draft",fake,a).getStatusCode().value());assertEquals(403,call("GET",BASE+"/profiles?environment=LIVE",null,root).getStatusCode().value());assertEquals(403,call("POST",BASE+"/profiles",Map.of("kind","ALIYUN_SMS","name","越权","scope",Map.of("ownerDeptId",Long.toString(COMPANY_B),"environment","TEST")),scoped(COMPANY_A,"biz:integration:create")).getStatusCode().value());assertEquals(403,call("PUT",path(p)+"/draft",draftBody(p,config(false),null),scoped(COMPANY_A,"biz:integration:query")).getStatusCode().value());assertEquals(0,ViJson.tree(call("GET",BASE+"/profiles",null,scopedWithScope(COMPANY_A,"5","biz:integration:query")).getBody()).path("total").asInt());}
 @Test void idempotentReplayAndParallelPublication(){var p=save(profile("TENCENT_SMS"),config(false),null);var body=publicationBody(p,local(p));String key=UUID.randomUUID().toString();var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->callKey("POST",path(p)+"/publish",body,root,key));var b=pool.submit(()->callKey("POST",path(p)+"/publish",body,root,key));assertEquals(data(a.get(20,TimeUnit.SECONDS)),data(b.get(20,TimeUnit.SECONDS)));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM vi_integration_publication",Integer.class));assertEquals(409,call("POST",path(p)+"/publish",body,root).getStatusCode().value());var altered=new LinkedHashMap<>(body);altered.put("reason","不同内容");assertEquals(409,callKey("POST",path(p)+"/publish",altered,root,key).getStatusCode().value());}catch(Exception e){throw new AssertionError(e);}finally{pool.shutdownNow();}}
