 @Test void sourcePytestAndAllTwelveResponseSchemas() throws Exception {var repo=java.nio.file.Path.of(System.getProperty("user.dir")).toAbsolutePath();if(!java.nio.file.Files.exists(repo.resolve("docs")))repo=repo.getParent();var source=repo.resolve("docs/vehicle/V6.4/13_真实集成测试/live");var dir=java.nio.file.Files.createTempDirectory("x01-pytest-");for(String name:List.of("x01-conftest.py","test_x01_contract.py")){try(var in=getClass().getResourceAsStream("/integration/"+name)){java.nio.file.Files.copy(in,dir.resolve(name.equals("x01-conftest.py")?"conftest.py":name));}}java.nio.file.Files.copy(source.resolve("test_integration_config.py"),dir.resolve("test_integration_config.py"));java.nio.file.Files.writeString(dir.resolve("pytest.ini"),"[pytest]\nmarkers =\n integration_config: real HTTP integration configuration\n");var pb=new ProcessBuilder(System.getenv("VI_PYTHON"),"-m","pytest",dir.toString(),"-q","--junitxml="+dir.resolve("result.xml")).directory(repo.toFile());var env=pb.environment();env.put("X01_SOURCE",source.toString());env.put("X01_BASE","http://127.0.0.1:"+port);env.put("X01_RUN",ViJson.write(Map.of("adminToken",root,"readOnlyToken",scoped(COMPANY_A,"biz:integration:query"),"ownerDeptId",Long.toString(COMPANY_A))));env.put("X01_MINI",mini());env.put("X01_DB_USER",dbUser);env.put("X01_DB_PASSWORD",dbPassword);pb.redirectErrorStream(true).redirectOutput(dir.resolve("output.log").toFile());var process=pb.start();assertTrue(process.waitFor(50,TimeUnit.SECONDS),"source pytest timeout");assertEquals(0,process.exitValue(),"Source pytest failed; private log: "+dir.resolve("output.log"));String xml=java.nio.file.Files.readString(dir.resolve("result.xml"));assertTrue(xml.contains("tests=\"9\""));System.out.println("X01_SOURCE_PYTEST: 9 passed; 12 response schemas checked");}
